// Alexa hands back completed items too; they are already dealt with.
if (!Array.isArray(msg.payload)) {
    msg.payload = [];
}
msg.payload = msg.payload.filter(i => !i.completed);
return msg;

// One Alexa "Shopping List" item -> one YAMP ad-hoc shopping-list add.
//
// Conservative on purpose. A unit YAMP refuses (imperial, spoons, cups) is a
// 422, and a 422 means the item is never removed from the Alexa list and is
// retried every 40s forever. So: convert what we know, and send anything
// doubtful as a bare name with no quantity at all.

const NAMESPACE = '1e6f2a4c-9d3b-4f27-8a55-2c0b7d914e63';

const WORDS = {
    one: 1, two: 2, three: 3, four: 4, five: 5, six: 6,
    seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12,
    couple: 2, dozen: 12
};

// Metric — YAMP canonicalises these to g/ml itself.
const METRIC = ['g', 'gram', 'grams', 'kg', 'kilogram', 'kilograms',
    'ml', 'millilitre', 'millilitres', 'milliliter', 'milliliters',
    'l', 'litre', 'litres', 'liter', 'liters'];

// YAMP's BANNED_UNITS, converted here with the factors its own ingest parser
// uses (INGEST_CONVERSIONS), so nothing ever comes back 422.
const CONVERT = {
    tsp: ['ml', 5], teaspoon: ['ml', 5], teaspoons: ['ml', 5],
    tbsp: ['ml', 15], tablespoon: ['ml', 15], tablespoons: ['ml', 15],
    cup: ['ml', 240], cups: ['ml', 240],
    oz: ['g', 28], ounce: ['g', 28], ounces: ['g', 28],
    lb: ['g', 454], lbs: ['g', 454], pound: ['g', 454], pounds: ['g', 454],
    pint: ['ml', 568], pints: ['ml', 568],
    quart: ['ml', 946], quarts: ['ml', 946],
    gallon: ['ml', 3785], gallons: ['ml', 3785],
    stick: ['g', 113], sticks: ['g', 113]
};

// Natural units worth keeping as a count. Anything not listed here is treated
// as part of the food's name, so "3 red peppers" stays 3 items of red pepper
// rather than 3 "red" of peppers.
const CONTAINERS = ['tin', 'tins', 'can', 'cans', 'jar', 'jars',
    'pack', 'packs', 'packet', 'packets', 'bottle', 'bottles',
    'box', 'boxes', 'bag', 'bags', 'carton', 'cartons',
    'bunch', 'bunches', 'punnet', 'punnets', 'tub', 'tubs',
    'loaf', 'loaves', 'clove', 'cloves', 'slice', 'slices',
    'sprig', 'sprigs', 'head', 'heads', 'roll', 'rolls'];

// Deterministic UUIDv5 from the Alexa item id. This is the idempotency key:
// the 40s poll and the ws-todo-change push can pick up the same item at the
// same moment, and YAMP returns 200 instead of double-adding.
function uuid5(name) {
    const ns = Buffer.from(NAMESPACE.replace(/-/g, ''), 'hex');
    const digest = crypto.createHash('sha1')
        .update(Buffer.concat([ns, Buffer.from(String(name), 'utf8')]))
        .digest();
    const b = Buffer.from(digest.subarray(0, 16));
    b[6] = (b[6] & 0x0f) | 0x50;
    b[8] = (b[8] & 0x3f) | 0x80;
    const s = b.toString('hex');
    return s.slice(0, 8) + '-' + s.slice(8, 12) + '-' + s.slice(12, 16) +
        '-' + s.slice(16, 20) + '-' + s.slice(20);
}

function withUnit(qty, unit, name) {
    const conv = CONVERT[unit];
    if (conv) {
        return { name: name.trim(), quantity: Math.round(qty * conv[1] * 1000) / 1000, unit: conv[0] };
    }
    return { name: name.trim(), quantity: qty, unit: unit };
}

function parse(text) {
    let s = String(text || '').toLowerCase().replace(/\s+/g, ' ').trim().replace(/[.!?]+$/, '');
    if (!s) return null;

    s = s.replace(/^(?:some|the)\s+/, '');
    // "half a cucumber" — the food is the cucumber, the half is not a quantity
    // YAMP can hold ("half" is not metric and not a countable unit).
    s = s.replace(/^half\s+(?:a|an|of)\s+/, '');

    // "2 x 400g tins of chopped tomatoes" — the metric amount already carries
    // the quantity, so the container word is dropped, same as YAMP's own
    // ingest parser does with the identical shape.
    const mult = s.match(/^(\d+(?:\.\d+)?)\s*x\s*(\d+(?:\.\d+)?)\s*([a-z]+)\b\.?\s*(?:of\s+)?(.+)$/);
    if (mult && (METRIC.indexOf(mult[3]) !== -1 || CONVERT[mult[3]])) {
        const rest = mult[4].replace(/^(?:tins?|cans?|jars?|packs?|packets?|bottles?)\s+(?:of\s+)?/, '');
        return withUnit(Number(mult[1]) * Number(mult[2]), mult[3], rest);
    }

    // "500g mince" — metric glued to the number.
    const glued = s.match(/^(\d+(?:\.\d+)?)\s*(g|kg|ml|l)\b\.?\s*(?:of\s+)?(.+)$/);
    if (glued) return withUnit(Number(glued[1]), glued[2], glued[3]);

    let qty = null;
    let article = false;
    let m = s.match(/^(\d+(?:\.\d+)?)\s+(.+)$/);
    if (m) {
        qty = Number(m[1]);
        s = m[2];
    } else {
        m = s.match(/^([a-z]+)\s+(.+)$/);
        if (m && WORDS[m[1]] !== undefined) {
            qty = WORDS[m[1]];
            s = m[2];
        } else if (m && (m[1] === 'a' || m[1] === 'an')) {
            // "a dozen eggs" — the article is in front of the number word.
            const after = m[2].match(/^([a-z]+)\s+(.+)$/);
            if (after && WORDS[after[1]] !== undefined) {
                qty = WORDS[after[1]];
                s = after[2];
            } else {
                qty = 1;
                article = true;
                s = m[2];
            }
        }
    }

    if (qty !== null) {
        const half = s.match(/^and\s+a\s+half\s+(.+)$/);
        if (half) {
            qty += 0.5;
            s = half[1];
        }
    }

    if (qty === null || !(qty > 0)) return { name: s, quantity: null, unit: null };

    const u = s.match(/^([a-z]+)\s+(?:of\s+)?(.+)$/);
    if (u && (METRIC.indexOf(u[1]) !== -1 || CONVERT[u[1]] || CONTAINERS.indexOf(u[1]) !== -1)) {
        return withUnit(qty, u[1], u[2]);
    }

    // A leading "a"/"an" with no unit behind it was only an article.
    if (article) return { name: s, quantity: null, unit: null };
    return { name: s, quantity: qty, unit: 'item' };
}

const item = msg.payload || {};
const parsed = parse(item.value);
if (!parsed || !parsed.name || parsed.name.length < 2) {
    node.warn('skipping unparseable Alexa item: ' + JSON.stringify(item));
    return null;
}

const token = env.get('YAMP_TOKEN');
if (!token) {
    node.error('YAMP_TOKEN is not set on the nodered container', msg);
    return null;
}

// Kept off msg.payload, which the http request node overwrites with the
// response. The removal branch downstream reads these back.
msg.alexa = {
    listId: item.listId || 'SHOP',
    itemId: item.id,
    version: Number(item.version),
    value: item.value
};
if (!msg.alexa.itemId || !isFinite(msg.alexa.version)) {
    node.warn('Alexa item has no id/version, it will not be removable: ' + JSON.stringify(item));
}

msg.url = (env.get('YAMP_URL') || 'https://meals.marcuslab.uk') + '/shopping-list/items';
msg.headers = {
    'Authorization': 'Bearer ' + token,
    'Content-Type': 'application/json',
    'X-Meals-Client': 'nodered-alexa/1.0 (1)'
};
msg.payload = { id: uuid5(item.id), name: parsed.name };
if (parsed.quantity > 0 && parsed.unit) {
    msg.payload.quantity = parsed.quantity;
    msg.payload.unit = parsed.unit;
}
return msg;
